import AppKit
import Carbon

/// 把文字写进当前焦点输入框。流程和时序参照 Typeless 的 InputHelper（insertText / simulatePasteCommand）：
///
///  1. 完整备份剪贴板：每个 item 的每种类型的原始数据（图片、文件、富文本都能恢复）
///  2. 写入文字，并标记 org.nspasteboard.TransientType / AutoGeneratedType：
///     Raycast、Paste、Maccy 等剪贴板管理器看到这个标记就不会记录这次写入
///  3. 等一小段时间：让 Fn 的修饰键状态真正释放，并给剪贴板 server 同步的时间
///  4. 用当前键盘布局查出 "v" 的 keycode（Dvorak / Colemak 下不是 9），发送 ⌘V
///  5. 目标 App 是异步读剪贴板的（Electron / 浏览器尤其慢），立刻恢复会粘贴成旧内容，
///     所以等 restoreDelay 之后再恢复；如果这期间 changeCount 变了（用户自己复制了东西），就不恢复
enum TextInserter {
    static let preDelay: UInt64 = 40_000_000          // 40 ms
    static let restoreDelay: UInt64 = 700_000_000     // 700 ms

    @MainActor
    static func insert(_ text: String, config: Config) async {
        if config.insertMode == "type" {
            typeUnicode(text)
            return
        }
        let pb = NSPasteboard.general
        let backup = config.restoreClipboard ? snapshot(pb) : nil

        pb.clearContents()
        let item = NSPasteboardItem()
        item.setString(text, forType: .string)
        item.setString("", forType: NSPasteboard.PasteboardType("org.nspasteboard.TransientType"))
        item.setString("", forType: NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType"))
        pb.writeObjects([item])
        let ourChangeCount = pb.changeCount

        try? await Task.sleep(nanoseconds: preDelay)
        postCommandV()

        guard let backup else { return }
        try? await Task.sleep(nanoseconds: restoreDelay)
        if pb.changeCount == ourChangeCount {
            restore(backup, to: pb)
        }
    }

    // MARK: - 剪贴板备份/恢复

    typealias Snapshot = [[(NSPasteboard.PasteboardType, Data)]]

    static func snapshot(_ pb: NSPasteboard) -> Snapshot {
        (pb.pasteboardItems ?? []).map { item in
            item.types.compactMap { type in item.data(forType: type).map { (type, $0) } }
        }
    }

    static func restore(_ snapshot: Snapshot, to pb: NSPasteboard) {
        pb.clearContents()
        guard !snapshot.isEmpty else { return }
        let items: [NSPasteboardItem] = snapshot.map { entries in
            let item = NSPasteboardItem()
            for (type, data) in entries { item.setData(data, forType: type) }
            return item
        }
        pb.writeObjects(items)
    }

    // MARK: - 模拟按键

    static func postCommandV() {
        let source = CGEventSource(stateID: .combinedSessionState)
        let vKey = keyCode(for: "v") ?? CGKeyCode(kVK_ANSI_V)
        let cmdKey = CGKeyCode(kVK_Command)

        // 显式发送 ⌘ 按下/松开：部分 App（Java、某些终端）检查真实修饰键状态而不是事件 flags
        let cmdDown = CGEvent(keyboardEventSource: source, virtualKey: cmdKey, keyDown: true)
        let vDown = CGEvent(keyboardEventSource: source, virtualKey: vKey, keyDown: true)
        let vUp = CGEvent(keyboardEventSource: source, virtualKey: vKey, keyDown: false)
        let cmdUp = CGEvent(keyboardEventSource: source, virtualKey: cmdKey, keyDown: false)
        cmdDown?.flags = .maskCommand
        vDown?.flags = .maskCommand   // 只带 ⌘，清掉可能残留的 Fn（maskSecondaryFn）
        vUp?.flags = .maskCommand
        cmdUp?.flags = []
        for e in [cmdDown, vDown, vUp, cmdUp] {
            e?.post(tap: .cghidEventTap)
        }
    }

    /// 在当前键盘布局里找到能打出 char 的 keycode。中文输入法下 TISCopyCurrentKeyboardLayoutInputSource
    /// 返回的是底层 ASCII 布局（通常是 ABC），正好是快捷键使用的布局。
    static func keyCode(for char: Character) -> CGKeyCode? {
        guard let source = TISCopyCurrentKeyboardLayoutInputSource()?.takeRetainedValue(),
              let ptr = TISGetInputSourceProperty(source, kTISPropertyUnicodeKeyLayoutData) else { return nil }
        let layoutData = Unmanaged<CFData>.fromOpaque(ptr).takeUnretainedValue() as Data
        let target = String(char)
        return layoutData.withUnsafeBytes { raw -> CGKeyCode? in
            guard let layout = raw.baseAddress?.assumingMemoryBound(to: UCKeyboardLayout.self) else { return nil }
            for code in 0..<128 {
                var deadKeyState: UInt32 = 0
                var length = 0
                var chars = [UniChar](repeating: 0, count: 4)
                let status = UCKeyTranslate(layout, UInt16(code), UInt16(kUCKeyActionDown), 0,
                                            UInt32(LMGetKbdType()), OptionBits(kUCKeyTranslateNoDeadKeysMask),
                                            &deadKeyState, chars.count, &length, &chars)
                if status == noErr, length == 1, String(utf16CodeUnits: chars, count: 1) == target {
                    return CGKeyCode(code)
                }
            }
            return nil
        }
    }

    /// 备用方案：不经过剪贴板，直接发 Unicode 键盘事件。适合禁止粘贴的输入框，
    /// 但部分 App（远程桌面、游戏、某些终端）会丢字，所以默认用粘贴。
    static func typeUnicode(_ text: String) {
        let source = CGEventSource(stateID: .combinedSessionState)
        let units = Array(text.utf16)
        var i = 0
        while i < units.count {
            var end = min(i + 16, units.count)
            // 不要把代理对（emoji 等）拆到两个事件里
            if end < units.count, UTF16.isLeadSurrogate(units[end - 1]) { end -= 1 }
            var chunk = Array(units[i..<end])
            for down in [true, false] {
                let e = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: down)
                e?.flags = []
                e?.keyboardSetUnicodeString(stringLength: chunk.count, unicodeString: &chunk)
                e?.post(tap: .cghidEventTap)
            }
            usleep(3000)
            i = end
        }
    }
}
